      "name": "LEGO Ninjago: Dragons Rising",
      "first_air_time": "2023-06-01",
      "overview": "After several realms combine to form one unstable realm, a Spinjitzu Master is tasked with training new heroes. They must save the world from the forces of evil by finding elemental dragons.",
      "primary_language": "eng",
      "primary_type": "series",
      "status": "Continuing",
